# 4.4 — tắt máy, khởi động lại, ngủ/thức: 1074, 6006, 6005, 6013, Kernel-Power 109/42/107/172, Kernel-General 12/13/1 — log System mẫu công khai (omerbenamram/evtx: system.evtx Win10 2017, 2-vss_7-System.evtx Win10 2018; DeepBlueCLI many-events-system.evtx Win7).
@ps evtx-rec mau/2-vss_7-System.evtx | ConvertFrom-Json | Where-Object { $_.rec -ge 361 -and $_.rec -le 390 -and $_.id -in 1074,6006,6005,6013,109,13,12,172 } | Sort-Object t | ForEach-Object { '{0}  {1,-15} {2}' -f $_.t.ToString('HH:mm:ss.fff'), ($_.nguon -replace 'Microsoft-Windows-',''), $_.id }
@ps evtx-rec mau/2-vss_7-System.evtx | ConvertFrom-Json | Where-Object rec -eq 361 | ForEach-Object { $_.data | Format-List param1,param2,param3,param4,param5,param6,param7 }
@ps evtx-rec mau/dbc-many-events-system.evtx | ConvertFrom-Json | Where-Object id -eq 1074 | Group-Object { $d = $_.data.'#text'; '{0} | {1} | {2}' -f (($d[0] -replace ' \(.*','') -split '\\')[-1], $d[4], $d[2] } | Sort-Object Count -Descending | Select-Object -First 7 Count,@{n='Tien trinh | Kieu | Ly do';e={$_.Name}} | Format-Table -AutoSize
@ps foreach ($f in 'mau/system.evtx','mau/2-vss_7-System.evtx','mau/dbc-many-events-system.evtx') { $truoc = $null; $bat = 0; evtx-rec $f 2>$null | ConvertFrom-Json | Where-Object id -in 6005,6006,6008,41 | Sort-Object t | ForEach-Object { if ($_.id -eq 6005 -and $truoc -eq 6005) { $bat++ }; $truoc = $_.id }; '{0,-32} khởi động không có 6006 trước đó: {1}' -f $f, $bat }
@ps evtx-rec mau/system.evtx | ConvertFrom-Json | Where-Object { $_.rec -ge 533 -and $_.rec -le 541 -and $_.id -in 42,107,1,6013 } | Sort-Object rec | ForEach-Object { '{0}  {1,-15} {2,-4} {3}' -f $_.t.ToString('MM-dd HH:mm:ss'), ($_.nguon -replace 'Microsoft-Windows-',''), $_.id, $(if ($_.id -eq 6013) { 'uptime ' + $_.data.'#text'[4] + ' giây' } else { ($_.data | ConvertTo-Json -Compress) -replace '"Programmed[^,]*,','' }) }
@ps evtx-rec mau/2-vss_7-System.evtx | ConvertFrom-Json | Where-Object id -eq 6013 | ForEach-Object { $s = [int]$_.data.'#text'[4]; '{0}  uptime {1,7} giây = {2:N1} ngày' -f $_.t.ToString('MM-dd HH:mm'), $s, ($s / 86400) } | Select-Object -First 9
@ps evtx-rec mau/system.evtx | ConvertFrom-Json | Where-Object id -eq 6013 | Select-Object -First 1 | ForEach-Object { $_.data.'#text' -join ' | ' }
# Bộ mẫu công khai không có Kernel-Power 41 / EventLog 6008 / BugCheck 1001 (máy mẫu đều tắt sạch) — đếm thật:
evtx-rec mau/*.evtx tc/*.evtx 2>/dev/null | jq -r 'select((.id==41 and (.nguon|test("Kernel-Power"))) or .id==6008 or (.id==1001 and (.nguon|test("BugCheck|WER-SystemErrorReporting")))) | .id' | wc -l
@ps evtx-rec mau/Application.evtx mau/dbc-many-events-application.evtx 2>$null | ConvertFrom-Json | Where-Object id -eq 1001 | Group-Object kenh,nguon | Select-Object Count,Name | Format-Table -AutoSize
